input.command:
python3 - <<'EOF'
import math
from ocean_sonar import report

def b(bc, tc, pc, fp, tt, tv):
    cv = round(tv/tt, 6)
    sc = round(100*(pc/tc)*(tv/tt), 6)
    return {"batch_count": bc, "tolerance_count": tc, "pass_count": pc,
            "fail_count": tc-pc, "first_pass_summary": fp,
            "terrain_total": tt, "terrain_valid": tv,
            "terrain_coverage": cv, "quality_score": sc}

# sc: 100*.5*1=50, 25, 75 ; ties then cv tie then index
b0 = b(2, 4, 2, 0, 10, 10)   # sc 50.0
b1 = b(3, 4, 1, 1, 10, 10)   # sc 25.0
b2 = b(1, 4, 3, 0, 10, 10)   # sc 75.0
r = report.rank_batches([b0, b1, b2])
assert list(r.keys()) == ["ranking", "score_spread"]
assert r["ranking"] == ((2, 75.0, 1.0), (0, 50.0, 1.0), (1, 25.0, 1.0)), r
assert r["score_spread"] == 50.0 and type(r["score_spread"]) is float

# tuple input + equal scores -> cv desc; equal sc/cv -> index asc
t0 = b(1, 2, 1, 0, 10, 4)   # sc 20, cv .4
t1 = b(1, 2, 1, 0, 10, 8)   # sc 40, cv .8
t2 = b(1, 4, 2, 0, 10, 8)   # sc 40, cv .8 (tie with t1)
r2 = report.rank_batches((t0, t1, t2))
assert r2["ranking"] == ((1, 40.0, 0.8), (2, 40.0, 0.8), (0, 20.0, 0.4)), r2
assert r2["score_spread"] == 20.0

# all equal -> spread 0.0 (not -0.0), ranking index order
r3 = report.rank_batches([t1, dict(t1)])
assert r3["ranking"] == ((0, 40.0, 0.8), (1, 40.0, 0.8))
assert r3["score_spread"] == 0.0 and math.copysign(1, r3["score_spread"]) > 0

# error checks
for bad, exc in [
    ([], ValueError),
    ({}, TypeError),
    ("x", TypeError),
    (None, TypeError),
]:
    try:
        report.rank_batches(bad)
    except exc:
        pass
    else:
        raise AssertionError(("container", bad))

# per-item prefix + type/value split
try:
    report.rank_batches([b1, "notadict"])
except TypeError as e:
    assert str(e) == "batches[1]: must be a dict", str(e)
else:
    raise AssertionError

wrong_keys = dict(b1); wrong_keys = {k: wrong_keys[k] for k in list(wrong_keys)[:-1]} | {"quality_score": 1.0}
# build a reordered-keys dict
reordered = {k: b1[k] for k in reversed(list(b1.keys()))}
try:
    report.rank_batches([reordered])
except TypeError as e:
    assert str(e).startswith("batches[0]: keys must be in the order"), str(e)
else:
    raise AssertionError

bad_type = b(1, 2.0, 1, 0, 10, 5)
try:
    report.rank_batches([bad_type])
except TypeError as e:
    assert str(e) == "batches[0]: tolerance_count must be a non-bool int", str(e)
else:
    raise AssertionError

bad_bool = b(1, True, 1, 0, 10, 5)
try:
    report.rank_batches([bad_bool])
except TypeError:
    pass
else:
    raise AssertionError

bad_rel = b(1, 2, 1, 0, 10, 11)  # tv > tt
try:
    report.rank_batches([b1, bad_rel])
except ValueError as e:
    assert str(e) == "batches[1]: terrain_valid must be in [0, terrain_total]", str(e)
else:
    raise AssertionError

bad_fc = dict(b1); bad_fc["fail_count"] = 0
try:
    report.rank_batches([b1, bad_fc])
except ValueError as e:
    assert str(e) == "batches[1]: fail_count must equal tolerance_count - pass_count", str(e)
else:
    raise AssertionError

# fp None when pc==0
z = b(1, 2, 0, None, 10, 5)
assert report.rank_batches([z])["ranking"][0][1] == 0.0
bad_fp = b(1, 2, 0, None, 10, 5); bad_fp["first_pass_summary"] = 0
try:
    report.rank_batches([bad_fp])
except ValueError:
    pass
else:
    raise AssertionError

# cv mismatch
bad_cv = dict(b1); bad_cv["terrain_coverage"] = 0.999999
try:
    report.rank_batches([bad_cv])
except ValueError as e:
    assert "terrain_coverage must equal" in str(e)
else:
    raise AssertionError

# nan sc -> ValueError
nan_b = dict(b1); nan_b["quality_score"] = float("nan")
try:
    report.rank_batches([nan_b])
except ValueError:
    pass
else:
    raise AssertionError

# input not modified
src = [b0, b1]
report.rank_batches(src)
assert src == [b0, b1]

assert "rank_batches" in report.__all__
assert hasattr(report, "rank_batches")
print("all smoke checks passed")
EOF
